export type UploadCategory = 'receipts' | 'employeeDocuments' | 'profilePhotos';

export interface StoredObjectMeta {
  /** The type we detected from the file's content, never the one the client claimed. */
  contentType: string;
  size: number;
  sha256: string;
  /** Cleaned original filename, kept as metadata only. Never part of the storage key. */
  originalName: string;
  uploadedBy: string;
  createdAt: string;
}

export interface StoredFile {
  body: Buffer;
  meta: StoredObjectMeta;
}

/**
 * What a storage backend must offer. Keys are opaque and always generated by the service.
 * A Cantobo/S3 adapter implements exactly this and must pass contracts/storage.contract.ts.
 */
export interface StorageAdapter {
  put(key: string, body: Buffer, meta: StoredObjectMeta): Promise<void>;
  get(key: string): Promise<StoredFile | null>;
  /** Returns true if something was deleted. */
  delete(key: string): Promise<boolean>;
  exists(key: string): Promise<boolean>;
}

export interface UploadRequest {
  category: UploadCategory;
  filename: string;
  declaredType: string;
  body: Buffer;
  uploadedBy: string;
}

export interface UploadResult {
  key: string;
  size: number;
  contentType: string;
  sha256: string;
  originalName: string;
}

export interface ScanInfo {
  contentType: string;
  size: number;
  originalName: string;
}

/** Virus-scan hook. Plug a real scanner (for example ClamAV) in here. */
export interface Scanner {
  scan(body: Buffer, info: ScanInfo): Promise<{ clean: boolean; reason?: string }>;
}

export interface DownloadLink {
  url: string;
  token: string;
  expiresAt: string;
}
